class Test(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return x.sin()

    @staticmethod
    def backward(ctx, grad_output):
        (x,) = ctx.saved_tensors
        before = a._version
        print(a, x)
        print(a._version, x._version)
        x.add_(1)
        print(a, x)
        print(a._version, x._version)
        return grad_output

a = torch.tensor(1.0, requires_grad=True)
a_replacement = a.clone()

def pack_hook(x):
    return a_replacement

def unpack_hook(x):
    return x

with torch.autograd.graph.saved_tensors_hooks(pack_hook, unpack_hook):
    b = Test.apply(a)

b.backward()
In backward, x and a don't actually share storage but have aliased version counters.
